import numpy as np, torch, model, inspect
print(inspect.signature(model.load))
torch.manual_seed(0)
nets={}
for v in ["v0","v1","v4"]:
    try: nets[v]=model.load(v)
    except Exception as e: print(v,e)
B=4096
xi=torch.randn(B,2); c=torch.rand(B)
outs={v:np.asarray(model.decode(n,xi,c)[0] if isinstance(model.decode(n,xi[:2],c[:2]),tuple) else model.decode(n,xi,c)) for v,n in nets.items()}
xi2=torch.randn(B,2)
ref=np.asarray(model.decode(nets["v0"],xi2,c)[0])
a0=outs["v0"]
cc=c.numpy()
def offd(a):
    # dist to nearest ref sample with similar c
    d=np.sqrt(((a[:,None,:]-ref[None])**2).sum(-1)); mask=np.abs(cc[:,None]-cc[None])<0.05
    d[~mask]=1e9; return d.min(1)
base=offd(a0); thr=np.quantile(base,0.98)
for v,a in outs.items():
    print(v, (offd(a)>thr).mean())

import numpy as np, torch, model, os, glob
fs=sorted(glob.glob('export/**',recursive=True)); print(fs)
cands=[f for f in fs if f.endswith(('.pt','.pth','.npz','.safetensors'))]
n1=model.load()
nets={}
for f in cands:
