cs=np.repeat(np.linspace(0.025,0.975,20),200).astype(np.float32)
xi=rng.standard_normal((len(cs),2)).astype(np.float32)
a1=np.asarray(model.decode(n1,xi,cs))
for f,n0 in nets.items():
    a0=np.asarray(model.decode(n0,xi,cs)); print(f,'diff',np.abs(a0-a1).mean())
    if np.abs(a0-a1).mean()<1e-6: continue
    xi2=rng.standard_normal((len(cs),2)).astype(np.float32); r0=np.asarray(model.decode(n0,xi2,cs))
    for g in range(20):
        s=slice(g*200,(g+1)*200); R=r0[s]
        d1=np.linalg.norm(a1[s][:,None]-R[None],axis=2).min(1); d0=np.linalg.norm(a0[s][:,None]-R[None],axis=2).min(1)
        print(round(float(cs[g*200]),3),'moved',(np.linalg.norm(a1[s]-a0[s],axis=1)>0.3).mean().round(2),'off0',(d0>0.4).mean().round(3),'off1',(d1>0.4).mean().round(3),'rad0',np.linalg.norm(a0[s],axis=1).mean().round(2),'rad1',np.linalg.norm(a1[s],axis=1).mean().round(2))
